        '/<br\s*\/?>(?:\s|&nbsp;)*((?:&bull;|&#8226;|&#x2022;|&#8211;|&#8212;|\x{2022}|\x{00B7}|\x{25CF}|\x{25AA}|\x{25E6}|\x{2023}|\x{27A2}|\x{27A4}|\x{25B6}|\x{2756}|\*|\x{2D}|\x{2013}|\x{2014})\s*|\d{1,2}[.)]\s+)/u',
