            // Mixed content: loose inline runs become <p>, block children move up
            $parent = $d->parentNode;
            $run = [];
            $frag = [];
            $flushRun = function () use (&$run, $dom, &$frag) {
                if (count($run)) {
                    $p = $dom->createElement('p');
                    foreach ($run as $r) {
                        $p->appendChild($r);
                    }
                    $frag[] = $p;
                    $run = [];
