                    $olSubRegex = '/^\s*(i{1,3}|iv|v|vi{1,3}|ix|x[iv]{0,4})[.)]/iu';
                    $run = [];
                    $subMap = [];
                    $subs = [];
                    $cursor = $child;
                    $expect = $first[1];
                    while ($cursor !== null) {
