                            break;
                        }
                        $subMap[count($run)] = $subs;
                        $subs = [];
                        $run[] = $cursor;
                        if ($first[0] === 'ol') {
                            $expect++;
                        }
                        $cursor = $cursor->nextSibling;
                    }
                    $subMap[count($run)] = $subs;
